def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = ''
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result += current_char + str(count)
            current_char = char
            count = 1
    result += current_char + str(count)
    return result

def camel_to_snake(s: str) -> str:
    result = []
    for i, c in enumerate(s):
        if c.isupper() and (i == 0 or not s[i-1].islower() or s[i-1].isnumeric()):
            result.append('_')
        result.append(c.lower())
    return ''.join(result)

def merge_intervals(iv: list) -> list:
    if not iv:
        return []

    # Sort intervals by start time
    iv.sort()

    # Merge overlapping intervals
    merged = [iv[0]]
    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1] + 1:
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)

    return merged

